self.addEventListener('install', function (event) {
  var requests = FILES.map(function (path) {
    return new Request(new URL(path, self.registration.scope).href, { cache: 'reload' });
  });
  event.waitUntil(
    caches.open(CACHE)
      .then(function (cache) { return cache.addAll(requests); })
      .then(function () { return self.skipWaiting(); })
  );
});

self.addEventListener('activate', function (event) {
  event.waitUntil(
    caches.keys()
      .then(function (names) {
        return Promise.all(names.filter(function (name) {
          return name.indexOf('bm-site-') === 0 && name !== CACHE;
        }).map(function (name) { return caches.delete(name); }));
      })
      .then(function () { return self.clients.claim(); })
  );
});

// A folder address (".../nazm-almuaeen/") is served by its index.html.
function cacheKey(url) {
  var key = url.origin + url.pathname;
  return key.charAt(key.length - 1) === '/' ? key + 'index.html' : key;
}

